package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.*;

public class FilteringParserDelegate_skipChildren_TriageGen0Test {

    private JsonParser mockParser;
    private TokenFilter mockFilter;
    private FilteringParserDelegate delegate;

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockFilter = mock(TokenFilter.class);
        // FilteringParserDelegate constructor: (JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches)
        delegate = new FilteringParserDelegate(mockParser, mockFilter, true, true);
    }

    /**
     * Tests that if the current token is not START_OBJECT or START_ARRAY,
     * the method returns 'this' immediately without calling nextToken().
     */
    @Test
    public void testSkipChildren_NotAStructStart_ReturnsThis() throws IOException {
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.VALUE_STRING);
        // Reflection/Internal access to _currToken via getCurrentToken if possible, 
        // but since we are testing the delegate, we rely on how it's initialized or mocked.
        // In the provided code, _currToken is a field. Since we can't set private fields easily without reflection,
        // we assume the delegate's state is driven by the underlying parser or internal state.
        // However, the code uses _currToken directly. In a real scenario, the delegate is initialized with a parser.

        // To trigger the first 'if', we need to ensure the internal _currToken is not START_OBJECT or START_ARRAY.
        // Since we cannot set _currToken directly without reflection, we assume the delegate is behaving 
        // according to its internal state. For the sake of this test, we simulate the state.

        // Note: In actual Jackson, _currToken is updated via nextToken(). 
        // For this unit test, we will simulate the behavior.

        // If we cannot manipulate _currToken, we simulate a scenario where it won't match.
        // Let's assume the delegate is behaving as if _currToken is VALUE_NUMBER_INT.

        // We use a spy to control the internal _currToken if it were accessible, 
        // but since it's a private field, we must assume the test environment allows 
        // the delegate to be in a state where _currToken is not a struct start.

        // Because we can't access _currToken, we rely on the fact that if it's not START_OBJECT/ARRAY,
        // it returns 'this'.

        // For the purpose of this test, we will assume the default state of a new delegate 
        // (which usually has a null or non-struct token).
        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
        verify(mockParser, never()).nextToken();
    }

    /**
     * Tests the logic when current token is START_OBJECT and it successfully 
     * finds the matching END_OBJECT.
     */
    @Test
    public void testSkipChildren_StartObject_Success() throws IOException {
        // We need to force _currToken to START_OBJECT. 
        // Since _currToken is private, we must use reflection to set it for testing.
        setInternalToken(delegate, JsonToken.START_OBJECT);

        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME, JsonToken.VALUE_STRING, JsonToken.END_OBJECT);
        // The delegate calls nextToken() which is overridden in FilteringParserDelegate to call mockParser.nextToken()

        // Note: FilteringParserDelegate.nextToken() calls mockParser.nextToken()
        // However, the code provided uses nextToken() which is a public method of the delegate.
        // In the provided snippet, the while loop calls nextToken().

        // We must mock the delegate's nextToken() or the parser's nextToken() depending on implementation.
        // In FilteringParserDelegate, nextToken() calls the underlying parser.

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
        verify(mockParser, atLeastOnce()).nextToken();
    }

    /**
     * Tests the logic when current token is START_ARRAY and it contains nested structures.
     */
    @Test
    public void testSkipChildren_StartArray_WithNestedStructures() throws IOException {
        setInternalToken(delegate, JsonToken.START_ARRAY);

        // Sequence:
        // 1. nextToken -> START_OBJECT (open becomes 2)
        // 2. nextToken -> END_OBJECT (open becomes 1)
        // 3. nextToken -> START_ARRAY (open becomes 2)
        // 4. nextToken -> END_ARRAY (open becomes 1)
        // 5. nextToken -> END_ARRAY (open becomes 0 -> return)
        when(mockParser.nextToken())
            .thenReturn(JsonToken.START_OBJECT)
            .thenReturn(JsonToken.END_OBJECT)
            .thenReturn(JsonToken.START_ARRAY)
            .thenReturn(JsonToken.END_ARRAY)
            .thenReturn(JsonToken.END_ARRAY);

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
    }

    /**
     * Tests the branch where nextToken() returns null (EOF).
     */
    @Test
    public void testSkipChildren_NullToken_ReturnsThis() throws IOException {
        setInternalToken(delegate, JsonToken.START_OBJECT);

        when(mockParser.nextToken()).thenReturn(null);

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
    }

    /**
     * Tests the branch where nextToken() returns a token that is neither struct start nor end.
     */
    @Test
    public void testSkipChildren_NonStructTokensInside() throws IOException {
        setInternalToken(delegate, JsonToken.START_OBJECT);

        // Sequence:
        // 1. nextToken -> FIELD_NAME (not struct)
        // 2. nextToken -> VALUE_STRING (not struct)
        // 3. nextToken -> END_OBJECT (open becomes 0)
        when(mockParser.nextToken())
            .thenReturn(JsonToken.FIELD_NAME)
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.END_OBJECT);

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
    }

    /**
     * Helper method to set the private _currToken field via reflection.
     */
    private void setInternalToken(FilteringParserDelegate target, JsonToken token) {
        try {
            java.lang.reflect.Field field = FilteringParserDelegate.class.getDeclaredField("_currToken");
            field.setAccessible(true);
            field.set(target, token);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
